  // RNG TRNG Miscellaneous Control Register
  struct RtmctlFields {
    enum class eSAMP_MODE : std::uint32_t {
      // use Von Neumann data into both Entropy shifter and Statistical Checker
      eVON_DATA_4_SHIFTER_N_CHECKER = 0,
      // use raw data into both Entropy shifter and Statistical Checker
      eRAW_DATA_4_SHIFTER_N_CHECKER = 1,
      // use Von Neumann data into Entropy shifter. Use raw data into Statistical Checker
      eVON_4_SHIFTER_N_RAW_4_CHECKER = 2,
    };

    enum class eOSC_DIV : std::uint32_t {
      // use ring oscillator with no divide
      eOSC_NOT_DIVIDED = 0,
      // use ring oscillator divided-by-2
      eOSC_DIVIDE_BY_2 = 1,
      // use ring oscillator divided-by-4
      eOSC_DIVIDE_BY_4 = 2,
      // use ring oscillator divided-by-8
      eOSC_DIVIDE_BY_8 = 3,
    };

    // Sample Mode
    using SAMP_MODE = ftl::mmio::Field<2, 0, eSAMP_MODE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Oscillator Divide
    using OSC_DIV = ftl::mmio::Field<2, 2, eOSC_DIV, ftl::mmio::RW, ftl::mmio::Normal>;
    // Clock Output Enable
    using CLK_OUT_EN = ftl::mmio::Field<1, 4, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // TRNG Access Mode
    using TRNG_ACC = ftl::mmio::Field<1, 5, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Reset Defaults
    using RST_DEF = ftl::mmio::Field<1, 6, bool, ftl::mmio::WO, ftl::mmio::Normal>;
    // Force System Clock
    using FORCE_SYSCLK = ftl::mmio::Field<1, 7, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Read only: Frequency Count Fail
    using FCT_FAIL = ftl::mmio::Field<1, 8, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Read only: Frequency Count Valid. Indicates that a valid frequency count may be read from RTFRQCNT.
    using FCT_VAL = ftl::mmio::Field<1, 9, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Read only: Entropy Valid
    using ENT_VAL = ftl::mmio::Field<1, 10, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Read only: Test point inside ring oscillator.
    using TST_OUT = ftl::mmio::Field<1, 11, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Read: Error status
    using ERR = ftl::mmio::Field<1, 12, bool, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // TRNG_OK_TO_STOP
    using TSTOP_OK = ftl::mmio::Field<1, 13, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Programming Mode Select
    using PRGM = ftl::mmio::Field<1, 16, bool, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct RtmctlFields

