    using eG2_WRITE = P0smaprPg0Fields::eG2_WRITE;
    using eG2_TDO = P0smaprPg0Fields::eG2_TDO;
    using eG2_SMBLOB = P0smaprPg0Fields::eG2_SMBLOB;
    using eSMAG_LCK = P0smaprPg0Fields::eSMAG_LCK;
    using eSMAP_LCK = P0smaprPg0Fields::eSMAP_LCK;
    using ePSP = P0smaprPg0Fields::ePSP;
    using eCSP = P0smaprPg0Fields::eCSP;
    using G1_READ = P0smaprPg0Fields::G1_READ;
