    using G2_TDO = P0smaprPg0Fields::G2_TDO;
    using G2_SMBLOB = P0smaprPg0Fields::G2_SMBLOB;
    using SMAG_LCK = P0smaprPg0Fields::SMAG_LCK;
    using SMAP_LCK = P0smaprPg0Fields::SMAP_LCK;
