    // Access Group 2 Write
    using G2_WRITE = ftl::mmio::Field<1, 5, eG2_WRITE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Trusted Descriptor Override
    using G2_TDO = ftl::mmio::Field<1, 6, eG2_TDO, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Secure Memory Blobs
    using G2_SMBLOB = ftl::mmio::Field<1, 7, eG2_SMBLOB, ftl::mmio::RW, ftl::mmio::Normal>;
    // SMAG LOCK bit
    using SMAG_LCK = ftl::mmio::Field<1, 12, eSMAG_LCK, ftl::mmio::RW, ftl::mmio::Normal>;
    // SMAP LOCK bit
    using SMAP_LCK = ftl::mmio::Field<1, 13, eSMAP_LCK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Public Security Parameters
    using PSP = ftl::mmio::Field<1, 14, ePSP, ftl::mmio::RW, ftl::mmio::Normal>;
    // Critical Security Parameters
