  // Recoverable Error Interrupt Halt
  struct ReihFields {
    enum class eCWDE : std::uint32_t {
      // Don't halt CAAM if CAAM watchdog expired.
      eDONT_HALT = 0,
      // Halt CAAM if CAAM watchdog expired..
      eHALT = 1,
    };

    enum class eRBAE : std::uint32_t {
      // Don't halt CAAM if RTIC-initiated job execution caused bus access error.
      eDONT_HALT = 0,
      // Halt CAAM if RTIC-initiated job execution caused bus access error.
      eHALT = 1,
    };

    enum class eJBAE0 : std::uint32_t {
      // Don't halt CAAM if JR0-initiated job execution caused bus access error.
      eDONT_HALT = 0,
      // Halt CAAM if JR0-initiated job execution caused bus access error.
      eHALT = 1,
    };

    enum class eJBAE1 : std::uint32_t {
      // Don't halt CAAM if JR1-initiated job execution caused bus access error.
      eDONT_HALT = 0,
      // Halt CAAM if JR1-initiated job execution caused bus access error.
      eHALT = 1,
    };

    enum class eJBAE2 : std::uint32_t {
      // Don't halt CAAM if JR2-initiated job execution caused bus access error.
      eDONT_HALT = 0,
      // Halt CAAM if JR2-initiated job execution caused bus access error.
      eHALT = 1,
    };

    enum class eJBAE3 : std::uint32_t {
      // Don't halt CAAM if JR3-initiated job execution caused bus access error.
      eDONT_HALT = 0,
      // Halt CAAM if JR3-initiated job execution caused bus access error.
      eHALT = 1,
    };

    // Halt CAAM if CAAM watchdog timer expires.
    using CWDE = ftl::mmio::Field<1, 0, eCWDE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Halt CAAM if RTIC-initiated job execution caused bus access error.
    using RBAE = ftl::mmio::Field<1, 16, eRBAE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Halt CAAM if JR0-initiated job execution caused bus access error.
    using JBAE0 = ftl::mmio::Field<1, 24, eJBAE0, ftl::mmio::RW, ftl::mmio::Normal>;
    // Halt CAAM if JR1-initiated job execution caused bus access error.
    using JBAE1 = ftl::mmio::Field<1, 25, eJBAE1, ftl::mmio::RW, ftl::mmio::Normal>;
    // Halt CAAM if JR2-initiated job execution caused bus access error.
    using JBAE2 = ftl::mmio::Field<1, 26, eJBAE2, ftl::mmio::RW, ftl::mmio::Normal>;
    // Halt CAAM if JR3-initiated job execution caused bus access error.
    using JBAE3 = ftl::mmio::Field<1, 27, eJBAE3, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct ReihFields

