  // Holding Tank 0 Job Queue Control, most-significant half
  struct Ht0JqCtrlMsFields {
    enum class eSRC : std::uint32_t {
      // Job Ring 0
      eJR0 = 0,
      // Job Ring 1
      eJR1 = 1,
      // Job Ring 2
      eJR2 = 2,
      // Job Ring 3
      eJR3 = 3,
      // RTIC
      eRTIC = 4,
    };

    enum class eJDDS : std::uint32_t {
      // Non-SEQ DID
      eNON_SEQ_DID = 0,
      // SEQ DID
      eSEQ_DID = 1,
    };

    enum class eHT_ERROR : std::uint32_t {
      // No error
      eNO_ERROR = 0,
      // Job Descriptor or Shared Descriptor length error
      eJD_OR_SD_LENGTH_ERROR = 1,
      // AXI_error while reading a Job Ring Shared Descriptor or the remainder of a Job Ring Job Descriptor
      eJD_OR_SD_READ_ERROR = 2,
    };

    enum class eDWORD_SWAP : std::uint32_t {
      // DWords are in the order most-significant word, least-significant word.
      eSRC_IN_MS_LS_ORDER = 0,
      // DWords are in the order least-significant word, most-significant word.
      eSRC_IN_LS_MS_ORDER = 1,
    };

    enum class eILE : std::uint32_t {
      // No byte-swapping is performed for immediate data transferred to or from the Descriptor Buffer.
      eNO_BYTE_SWAP = 0,
      // Byte-swapping is performed for immediate data transferred to or from the Descriptor Buffer.
      eBYTE_SWAP = 1,
    };

    // Job ID
    using ID = ftl::mmio::Field<3, 0, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Job Source
    using SRC = ftl::mmio::Field<3, 8, eSRC, ftl::mmio::RO, ftl::mmio::Normal>;
    // Job Descriptor DID Select
    using JDDS = ftl::mmio::Field<1, 14, eJDDS, ftl::mmio::RO, ftl::mmio::Normal>;
    // Allow Make Trusted Descriptor
    using AMTD = ftl::mmio::Field<1, 15, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Shared or Burst
    using SOB = ftl::mmio::Field<1, 16, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Holding Tank Error. (This field is implemented only in versions of CAAM that support prefetching.)
    using HT_ERROR = ftl::mmio::Field<2, 17, eHT_ERROR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Double Word Swap.
    using DWORD_SWAP = ftl::mmio::Field<1, 19, eDWORD_SWAP, ftl::mmio::RO, ftl::mmio::Normal>;
    // Share From
    using SHR_FROM = ftl::mmio::Field<5, 22, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Immediate Little Endian
    using ILE = ftl::mmio::Field<1, 27, eILE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Four Words. Job Queue Controller will pass at least 4 words of the descriptor to DECO.
    using FOUR = ftl::mmio::Field<1, 28, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Whole Descriptor
    using WHL = ftl::mmio::Field<1, 29, bool, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct Ht0JqCtrlMsFields

