  // Compile Time Parameters Register, most-significant half
  struct CtprMsFields {
    // Job Ring Virtualization programmable
    using VIRT_EN_INCL = ftl::mmio::Field<1, 0, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Job Ring Virtualization POR state
    using VIRT_EN_POR_VALUE = ftl::mmio::Field<1, 1, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // CAAM register page size. 0: CAAM uses 4Kbyte register pages. 1: CAAM uses 64Kbyte register pages.
    using REG_PG_SIZE = ftl::mmio::Field<1, 4, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // RNG Instantiations
    using RNG_I = ftl::mmio::Field<3, 8, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // AIOP interface implemented
    using AI_INCL = ftl::mmio::Field<1, 11, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // ICIDs with AMQs supported
    using DPAA2 = ftl::mmio::Field<1, 13, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // IP Bus Slave Clock
    using IP_CLK = ftl::mmio::Field<1, 14, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Burst Configurability If MCFG_BURST is 0, the normal burst size is limited to 32 bytes and large bursts cannot be enabled
    using MCFG_BURST = ftl::mmio::Field<1, 16, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Pointer Size field implemented 0: The Master Configuration Register does not contain a Pointer Size field
    using MCFG_PS = ftl::mmio::Field<1, 17, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Eight Scatter-Gather Tables implemented 0: CAAM implements one Scatter-Gather Table register
    using SG8 = ftl::mmio::Field<1, 18, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Performance Monitor Event Bus implemented 0: CAAM does not implement a Performance Monitor Event Bus
    using PM_EVT_BUS = ftl::mmio::Field<1, 19, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // DECO Watchdog Counter implemented 0: CAAM does not implement a DECO Watchdog Counter
    using DECO_WD = ftl::mmio::Field<1, 20, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Performance Counter registers implemented 0: CAAM does not implement Performance Counter registers
    using PC = ftl::mmio::Field<1, 21, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Separate C1 and C2 registers 0: In this implementation of CAAM the Class 2 Key and Context registers are shared with the Class 1 Key and Context registers
    using C1C2 = ftl::mmio::Field<1, 23, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // System/user partition-based CAAM IP Bus register access control 0: CAAM does not implement partition-based access control for its IP Bus registers, i
    using ACC_CTL = ftl::mmio::Field<1, 24, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Queue Manager interface (QI) implemented
    using QI = ftl::mmio::Field<1, 25, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // AXI Master Priority implemented
    using AXI_PRI = ftl::mmio::Field<1, 26, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // LIODN logic included
    using AXI_LIODN = ftl::mmio::Field<1, 27, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // AXI Pipeline Depth
    using AXI_PIPE_DEPTH = ftl::mmio::Field<4, 28, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct CtprMsFields

