    // IPSEC protocols
    using IPSEC = ftl::mmio::Field<1, 5, eIPSEC, ftl::mmio::RO, ftl::mmio::Normal>;
    // IKE protocols
    using IKE = ftl::mmio::Field<1, 6, eIKE, ftl::mmio::RO, ftl::mmio::Normal>;
    // SSL/TLS protocol
    using SSL_TLS = ftl::mmio::Field<1, 7, eSSL_TLS, ftl::mmio::RO, ftl::mmio::Normal>;
    // TLS PRF protocol
    using TLS_PRF = ftl::mmio::Field<1, 8, eTLS_PRF, ftl::mmio::RO, ftl::mmio::Normal>;
    // MACSEC protocol
    using MACSEC = ftl::mmio::Field<1, 9, eMACSEC, ftl::mmio::RO, ftl::mmio::Normal>;
    // RSA protocol
    using RSA = ftl::mmio::Field<1, 10, eRSA, ftl::mmio::RO, ftl::mmio::Normal>;
