    // Double CRC protocol
    using DBL_CRC = ftl::mmio::Field<1, 12, eDBL_CRC, ftl::mmio::RO, ftl::mmio::Normal>;
    // Manufacturing Protection protocol
    using MAN_PROT = ftl::mmio::Field<1, 13, eMAN_PROT, ftl::mmio::RO, ftl::mmio::Normal>;
    // Derived Key Protocol
    using DKP = ftl::mmio::Field<1, 14, eDKP, ftl::mmio::RO, ftl::mmio::Normal>;
