  // Job Ring Interrupt Status Register for Job Ring 1
  struct JrintrJr1Fields {
    enum class eERR_TYPE : std::uint32_t {
      // Error writing status to Output Ring
      eOR_WR_ERR = 1,
      // Bad input ring base address (not on a 4-byte boundary).
      eBAD_IR_ADDR_ERR = 3,
      // Bad output ring base address (not on a 4-byte boundary).
      eBAD_OR_ADDR_ERR = 4,
      // Invalid write to Input Ring Base Address Register or Input Ring Size Register. Can be written when there are no jobs in the input ring or when the Job Ring is halted. These are fatal and will likely result in not being able to get all jobs out into the output ring for processing by software. Resetting the job ring will almost certainly be necessary.
      eINV_IR_REG_WR_ERR = 5,
      // Invalid write to Output Ring Base Address Register or Output Ring Size Register. Can be written when there are no jobs in the output ring and no jobs from this queue are already processing in CAAM (in the holding tanks or DECOs), or when the Job Ring is halted.
      eINV_OR_REG_WR_ERR = 6,
      // Job Ring reset released before Job Ring is halted.
      eINV_JR_RESET_ERR = 7,
      // Removed too many jobs (ORJRR larger than ORSFR).
      eORJRR_GT_ORSFR_ERR = 8,
      // Added too many jobs (IRJAR larger than IRSAR).
      eIRJAR_GT_IRSAR_ERR = 9,
      // Writing ORSF > ORS In these error cases the write is ignored, the interrupt is asserted (unless masked) and the error bit and error_type fields are set in the Job Ring Interrupt Status Register.
      eORSF_GT_ORS_ERR = 10,
      // Writing IRSA > IRS
      eIRSA_GT_IRS_ERR = 11,
      // Writing ORWI > ORS in bytes
      eORWI_GT_ORS_ERR = 12,
      // Writing IRRI > IRS in bytes
      eIRRI_GT_IRS_ERR = 13,
      // Writing IRSA when ring is active
      eINV_IRSA_WR_ERR = 14,
      // Writing IRRI when ring is active
      eINV_IRRI_WR_ERR = 15,
      // Writing ORSF when ring is active
      eINV_ORSF_WR_ERR = 16,
      // Writing ORWI when ring is active
      eINV_ORWI_WR_ERR = 17,
    };

    // Job Ring Interrupt
    using JRI = ftl::mmio::Field<1, 0, bool, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Job Ring Error
    using JRE = ftl::mmio::Field<1, 1, bool, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Halt the Job Ring
    using HALT = ftl::mmio::Field<2, 2, std::uint8_t, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Enter SNVS Fail State
    using ENTER_FAIL = ftl::mmio::Field<1, 4, bool, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Exit SNVS Fail State
    using EXIT_FAIL = ftl::mmio::Field<1, 5, bool, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Error type
    using ERR_TYPE = ftl::mmio::Field<5, 8, eERR_TYPE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Output ring write index with error
    using ERR_ORWI = ftl::mmio::Field<14, 16, std::uint16_t, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct JrintrJr1Fields

