  // Job Ring Configuration Register for Job Ring 1, least-significant half
  struct JrcfgrJr1LsFields {
    enum class eIMSK : std::uint32_t {
      // Interrupt enabled.
      eINTR_ENABLED = 0,
      // Interrupt masked.
      eINTR_MASKED = 1,
    };

    enum class eICEN : std::uint32_t {
      // Interrupt coalescing is disabled. If the IMSK bit is cleared, an interrupt is asserted whenever a job is written to the output ring. ICDCT is ignored. Note that if software removes one or more jobs and clears the interrupt but the output rings slots full is still greater than 0 (ORSF > 0), then the interrupt will clear but reassert on the next clock cycle.
      eINTR_COAL_DISABLED = 0,
      // Interrupt coalescing is enabled. If the IMSK bit is cleared, an interrupt is asserted whenever the threshold number of frames is reached (ICDCT) or when the threshold timer expires (ICTT). Note that if software removes one or more jobs and clears the interrupt but the interrupt coalescing threshold is still met (ORSF >= ICDCT), then the interrupt will clear but reassert on the next clock cycle.
      eINTR_COAL_ENABLED = 1,
    };

    // Interrupt Mask. Mask the interrupt that is associated with the particular processor.
    using IMSK = ftl::mmio::Field<1, 0, eIMSK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Interrupt Coalescing Enable.
    using ICEN = ftl::mmio::Field<1, 1, eICEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Interrupt Coalescing Descriptor Count Threshold
    using ICDCT = ftl::mmio::Field<8, 8, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Interrupt Coalescing Timer Threshold
    using ICTT = ftl::mmio::Field<16, 16, std::uint16_t, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct JrcfgrJr1LsFields

