  // Secure Memory Access Permissions register
  struct P11smaprJr2Fields {
    enum class eG1_READ : std::uint32_t {
      // Instruction fetches and reads are prohibited (except that Trusted Descriptor reads (if G1_TDO=1) and key-reads are always allowed, and exporting Secure Memory Blobs is allowed if G1_SMBLOB=1 or if done by a Trusted Descriptor and G1_TDO=1).
      eG1_READ_PROHIB = 0,
      // Instruction fetches and reads are allowed (but exporting a Secure Memory Blob is prohibited if G1_SMBLOB=0 and the descriptor is not a Trusted Descriptor or if G1_TDO=0).
      eG1_READ_ALLOWED = 1,
    };

    enum class eG1_WRITE : std::uint32_t {
      // Writes are prohibited (except that Trusted Descriptor writes are allowed, and importing Secure Memory Blobs is allowed if G1_SMBLOB=1 or if done by a Trusted Descriptor and G1_TDO=1).
      eG1_WRITE_PROHIB = 0,
      // Writes are allowed (but importing a Secure Memory Blob is prohibited if G1_SMBLOB=0 and the descriptor is not a Trusted Descriptor or if G1_TDO=0).
      eG1_WRITE_ALLOWED = 1,
    };

    enum class eG1_TDO : std::uint32_t {
      // Trusted Descriptors have the same access privileges as Job Descriptors
      eG1_TD_PRIVILEGE_AS_JD = 0,
      // Trusted Descriptors are allowed to override the other access permissions, i.e. they can export blobs from or import blobs to the partition and read from and write to the partition regardless of the G1_SMBLOB, G1_WRITE and G1_READ settings.
      eG1_TD_OVERIDE_ALLOWED = 1,
    };

    enum class eG1_SMBLOB : std::uint32_t {
      // Exporting or importing Secure Memory Blobs is prohibited, unless done via a Trusted Descriptor and G1_TDO=1.
      eG1_SM_BLOB_EXPORT_IMPORT_PROHIB = 0,
      // Exporting or importing Secure Memory Blobs is allowed, regardless of the G1_READ and G1_WRITE settings.
      eG1_SM_B_EXPORT_IMPORT_ALLOWED = 1,
    };

    enum class eG2_READ : std::uint32_t {
      // Instruction fetches and reads are prohibited (except that Trusted Descriptor reads (if G2_TDO=1) and key-reads are always allowed, and exporting Secure Memory Blobs is allowed if G2_SMBLOB=1 or if done by a Trusted Descriptor and G2_TDO=1).
      eG2_READ_PROHIB = 0,
      // Instruction fetches and reads are allowed (but exporting a Secure Memory Blob is prohibited if G2_SMBLOB=0 and the descriptor is not a Trusted Descriptor or if G2_TDO=0).
      eG2_READ_ALLOWED = 1,
    };

    enum class eG2_WRITE : std::uint32_t {
      // Writes are prohibited (except that Trusted Descriptor writes are allowed, and importing Secure Memory Blobs is allowed if G2_SMBLOB=1 or if done by a Trusted Descriptor and G2_TDO=1).
      eG2_WRITE_PROHIB = 0,
      // Writes are allowed (but importing a Secure Memory Blob is prohibited if G2_SMBLOB=0 and the descriptor is not a Trusted Descriptor or if G2_TDO=0).
      eG2_WRITE_ALLOWED = 1,
    };

    enum class eG2_TDO : std::uint32_t {
      // Trusted Descriptors have the same access privileges as Job Descriptors
      eG2_TD_PRIVILEGE_AS_JD = 0,
      // Trusted Descriptors are allowed to override the other access permissions, i.e. they can export blobs from or import blobs to the partition and read from and write to the partition regardless of the G2_SMBLOB, G2_WRITE and G2_READ settings.
      eG2_TD_OVERIDE_ALLOWED = 1,
    };

    enum class eG2_SMBLOB : std::uint32_t {
      // Exporting or importing Secure Memory Blobs is prohibited, unless done via a Trusted Descriptor and G2_TDO=1.
      eG2_SM_BLOB_EXPORT_IMPORT_PROHIB = 0,
      // Exporting or importing Secure Memory Blobs is allowed, regardless of the G2_READ and G2_WRITE settings.
      eG2_SM_BLOB_EXPORT_IMPORT_ALLOWED = 1,
    };

    enum class eSMAG_LCK : std::uint32_t {
      // The SMAG2JR register and SMAG1JR register are unlocked. The partition owner can change any writable bits of these registers.
      eSMAG_UNLOCKED = 0,
      // The SMAG2JR register and SMAG1JR register are locked. The SMAG2JR and SMAG1JR registers cannot be changed until the partition is de-allocated or a POR occurs.
      eSMAG_LOCKED = 1,
    };

    enum class eSMAP_LCK : std::uint32_t {
      // The SMAP register is unlocked. The partition owner can change any writable bits of the SMAP register.
      eSMAP_UNLOCKED = 0,
      // The SMAP register is locked. The SMAP_LCK, CSP and PSP bits and G1 and G2 permission bits of the SMAP register cannot be changed until the partition is de-allocated or a POR occurs. The PARTITION_KMOD value can still be changed. The SMAG_LCK bit can be changed to a 1, but cannot be changed to a 0.
      eSMAP_LOCKED = 1,
    };

    enum class ePSP : std::uint32_t {
      // The partition and any of the pages allocated to the partition can be de-allocated.
      eNOT_DEALLOCATABLE = 0,
      // The partition cannot be de-allocated and the pages allocated to the partition cannot be de-allocated.
      eDEALLOCATABLE = 1,
    };

    enum class eCSP : std::uint32_t {
      // The pages allocated to the partition will not be zeroized when they are de-allocated or the partition is released or a security alarm occurs.
      eNOT_ZEROIZED = 0,
      // The pages allocated to the partition will be zeroized when they are individually de-allocated or the partition is released or a security alarm occurs.
      eZEROIZED = 1,
    };

    // Access Group 1 Read
    using G1_READ = ftl::mmio::Field<1, 0, eG1_READ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 1 Write
    using G1_WRITE = ftl::mmio::Field<1, 1, eG1_WRITE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 1 Trusted Descriptor Override
    using G1_TDO = ftl::mmio::Field<1, 2, eG1_TDO, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 1 Secure Memory Blobs
    using G1_SMBLOB = ftl::mmio::Field<1, 3, eG1_SMBLOB, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Read
    using G2_READ = ftl::mmio::Field<1, 4, eG2_READ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Write
    using G2_WRITE = ftl::mmio::Field<1, 5, eG2_WRITE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Trusted Descriptor Override
    using G2_TDO = ftl::mmio::Field<1, 6, eG2_TDO, ftl::mmio::RW, ftl::mmio::Normal>;
    // Access Group 2 Secure Memory Blobs
    using G2_SMBLOB = ftl::mmio::Field<1, 7, eG2_SMBLOB, ftl::mmio::RW, ftl::mmio::Normal>;
    // SMAG LOCK bit
    using SMAG_LCK = ftl::mmio::Field<1, 12, eSMAG_LCK, ftl::mmio::RW, ftl::mmio::Normal>;
    // SMAP LOCK bit
    using SMAP_LCK = ftl::mmio::Field<1, 13, eSMAP_LCK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Public Security Parameters
    using PSP = ftl::mmio::Field<1, 14, ePSP, ftl::mmio::RW, ftl::mmio::Normal>;
    // Critical Security Parameters
    using CSP = ftl::mmio::Field<1, 15, eCSP, ftl::mmio::RW, ftl::mmio::Normal>;
    // The value in this field is used to modify the Blob Key Encryption Key when exporting cryptographic Blobs from, or importing cryptographic Blobs to, this partition
    using PARTITION_KMOD = ftl::mmio::Field<16, 16, std::uint16_t, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct P11smaprJr2Fields

