    using Gx_ID05 = ftl::mmio::Field<1, 5, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bit set to 1 indicates SecureWorld DID 06 is a member of Access Group x (1 or 2).
    using Gx_ID06 = ftl::mmio::Field<1, 6, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bit set to 1 indicates SecureWorld DID 07 is a member of Access Group x (1 or 2).
    using Gx_ID07 = ftl::mmio::Field<1, 7, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bit set to 1 indicates SecureWorld DID 08 is a member of Access Group x (1 or 2).
    using Gx_ID08 = ftl::mmio::Field<1, 8, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bit set to 1 indicates SecureWorld DID 09 is a member of Access Group x (1 or 2).
    using Gx_ID09 = ftl::mmio::Field<1, 9, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Bit set to 1 indicates SecureWorld DID 10 is a member of Access Group x (1 or 2).
    using Gx_ID10 = ftl::mmio::Field<1, 10, bool, ftl::mmio::RW, ftl::mmio::Normal>;
