  // RTIC Status Register
  struct RstaFields {
    enum class eBSY : std::uint32_t {
      // RTIC Idle.
      eIDLE = 0,
      // RTIC Busy.
      eBUSY = 1,
    };

    enum class eHD : std::uint32_t {
      // Boot authentication disabled
      eBOOT_AUTH_DISABLED = 0,
      // Authenticate code/generate reference hash value. This bit cannot be modified during run-time checking mode.
      eBOOT_AUTH_ENABLED = 1,
    };

    enum class eSV : std::uint32_t {
      // Memory block contents authenticated.
      eBLOCKS_AUTHENTICATED = 0,
      // Memory block hash doesn't match reference value.
      eBLOCKS_HASH_MISMATCH = 1,
    };

    enum class eHE : std::uint32_t {
      // Memory block contents authenticated.
      eBLOCKS_AUTHENTICATED = 0,
      // Memory block hash doesn't match reference value.
      eBLOCKS_HASH_MISMATCH = 1,
    };

    enum class eMIS : std::uint32_t {
      // Memory Block X is valid or state unknown
      eVALID_OR_UNKNOWN = 0,
      // Memory Block X has been corrupted
      eCORRUPTED = 1,
    };

    enum class eAE : std::uint32_t {
      // All reads by RTIC were valid.
      eADDR_VALID = 0,
      // An illegal address was accessed by the RTIC
      eADDR_ERROR = 1,
    };

    enum class eWE : std::uint32_t {
      // No RTIC Watchdog timer error has occurred.
      eWATCHDOG_GOING = 0,
      // RTIC Watchdog timer has expired prior to completing a round of hashing.
      eWATCHDOG_ERROR = 1,
    };

    enum class eCS : std::uint32_t {
      // Idle State
      eIDLE = 0,
      // Single Hash State
      eSINGLE_HASH = 1,
      // Run-time State
      eRUN_TIME = 2,
      // Error State
      eERROR = 3,
    };

    // RTIC Idle/Busy Status. When busy, the RTIC cannot be written to.
    using BSY = ftl::mmio::Field<1, 0, eBSY, ftl::mmio::RO, ftl::mmio::Normal>;
    // Hash Once Operation Completed (Hash Done)
    using HD = ftl::mmio::Field<1, 1, eHD, ftl::mmio::RO, ftl::mmio::Normal>;
    // Security Violation
    using SV = ftl::mmio::Field<1, 2, eSV, ftl::mmio::RO, ftl::mmio::Normal>;
    // Hashing Error
    using HE = ftl::mmio::Field<1, 3, eHE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Memory Integrity Status
    using MIS = ftl::mmio::Field<4, 4, eMIS, ftl::mmio::RO, ftl::mmio::Normal>;
    // Address Error
    using AE = ftl::mmio::Field<4, 8, eAE, ftl::mmio::RO, ftl::mmio::Normal>;
    // RTIC Watchdog Error
    using WE = ftl::mmio::Field<1, 16, eWE, ftl::mmio::RO, ftl::mmio::Normal>;
    // All Blocks Hashed
    using ABH = ftl::mmio::Field<1, 17, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Hash Once Blocks Disabled
    using HOD = ftl::mmio::Field<1, 18, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // Run Time Blocks Disabled
    using RTD = ftl::mmio::Field<1, 19, bool, ftl::mmio::RO, ftl::mmio::Normal>;
    // RTIC Current State. Indicates the current state of the RTIC controller.
    using CS = ftl::mmio::Field<2, 25, eCS, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct RstaFields

