  // CCB 0 Clear Written Register
  struct C0cwrFields {
    enum class eC1M : std::uint32_t {
      // Don't clear the Class 1 Mode Register.
      eDONT_CLEAR_C1_MODE = 0,
      // Clear the Class 1 Mode Register.
      eCLEAR_C1_MODE = 1,
    };

    enum class eC1DS : std::uint32_t {
      // Don't clear the Class 1 Data Size Register.
      eDONT_CLEAR_C1_DATA_SIZE = 0,
      // Clear the Class 1 Data Size Register.
      eCLEAR_C1_DATA_SIZE = 1,
    };

    enum class eC1ICV : std::uint32_t {
      // Don't clear the Class 1 ICV Size Register.
      eDONT_CLEAR_C1_ICV_SIZE = 0,
      // Clear the Class 1 ICV Size Register.
      eCLEAR_C1_ICV_SIZE = 1,
    };

    enum class eC1C : std::uint32_t {
      // Don't clear the Class 1 Context Register.
      eDONT_CLEAR_C1_CTXR = 0,
      // Clear the Class 1 Context Register.
      eCLEAR_C1_CTXR = 1,
    };

    enum class eC1K : std::uint32_t {
      // Don't clear the Class 1 Key Register.
      eDONT_CLEAR_C1_KEYR = 0,
      // Clear the Class 1 Key Register.
      eCLEAR_C1_KEYR = 1,
    };

    enum class eCPKA : std::uint32_t {
      // Don't clear the PKHA A Size Register.
      eDONT_CLEAR_PKHA_A_SIZE = 0,
      // Clear the PKHA A Size Register.
      eCLEAR_PKHA_A_SIZE = 1,
    };

    enum class eCPKB : std::uint32_t {
      // Don't clear the PKHA B Size Register.
      eDONT_CLEAR_PKHA_B_SIZE = 0,
      // Clear the PKHA B Size Register.
      eCLEAR_PKHA_B_SIZE = 1,
    };

    enum class eCPKN : std::uint32_t {
      // Don't clear the PKHA N Size Register.
      eDONT_CLEAR_PKHA_N_SIZE = 0,
      // Clear the PKHA N Size Register.
      eCLEAR_PKHA_N_SIZE = 1,
    };

    enum class eCPKE : std::uint32_t {
      // Don't clear the PKHA E Size Register..
      eDONT_CLEAR_PKHA_E_SIZE = 0,
      // Clear the PKHA E Size Register.
      eCLEAR_PKHA_E_SIZE = 1,
    };

    enum class eC2M : std::uint32_t {
      // Don't clear the Class 2 Mode Register.
      eDONT_CLEAR_C2_MODE = 0,
      // Clear the Class 2 Mode Register.
      eCLEAR_C2_MODE = 1,
    };

    enum class eC2DS : std::uint32_t {
      // Don't clear the Class 2 Data Size Register.
      eDONT_CLEAR_C2_DATA_SIZE = 0,
      // Clear the Class 2 Data Size Register.
      eCLEAR_C2_DATA_SIZE = 1,
    };

    enum class eC2C : std::uint32_t {
      // Don't clear the Class 2 Context Register.
      eDONT_CLEAR_C2_CTXR = 0,
      // Clear the Class 2 Context Register.
      eCLEAR_C2_CTXR = 1,
    };

    enum class eC2K : std::uint32_t {
      // Don't clear the Class 2 Key Register.
      eDONT_CLEAR_C2_KEYR = 0,
      // Clear the Class 2 Key Register.
      eCLEAR_C2_KEYR = 1,
    };

    enum class eCDS : std::uint32_t {
      // Don't clear the shared descriptor signal.
      eDONT_CLEAR_SD_SIGNAL = 0,
      // Clear the shared descriptor signal.
      eCLEAR_SD_SIGNAL = 1,
    };

    enum class eC2D : std::uint32_t {
      // Don't clear the Class 2 done interrrupt.
      eDONT_CLEAR_C2_DONE_INT = 0,
      // Clear the Class 2 done interrrupt.
      eCLEAR_C2_DONE_INT = 1,
    };

    enum class eC1D : std::uint32_t {
      // Don't clear the Class 1 done interrrupt.
      eDONT_CLEAR_C1_DONE_INT = 0,
      // Clear the Class 1 done interrrupt.
      eCLEAR_C1_DONE_INT = 1,
    };

    enum class eC2RST : std::uint32_t {
      // Don't reset the Class 2 CHA.
      eDONT_RESET_C2_CHA = 0,
      // Reset the Class 2 CHA.
      eRESET_C2_CHA = 1,
    };

    enum class eC1RST : std::uint32_t {
      // Don't reset the Class 1 CHA.
      eDONT_RESET_C1_CHA = 0,
      // Reset the Class 1 CHA.
      eRESET_C1_CHA = 1,
    };

    enum class eCOF : std::uint32_t {
      // Don't clear the OFIFO.
      eDONT_CLEAR_OFIFO = 0,
      // Clear the OFIFO.
      eCLEAR_OFIFO = 1,
    };

    enum class eCIF : std::uint32_t {
      // Don't clear the IFIFO.
      eDONT_CLEAR_IFIFO = 0,
      // Clear the IFIFO.
      eCLEAR_IFIFO = 1,
    };

    // Clear the Class 1 Mode Register
    using C1M = ftl::mmio::Field<1, 0, eC1M, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 1 Data Size Register
    using C1DS = ftl::mmio::Field<1, 2, eC1DS, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 1 ICV Size Register
    using C1ICV = ftl::mmio::Field<1, 3, eC1ICV, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 1 Context Register
    using C1C = ftl::mmio::Field<1, 5, eC1C, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 1 Key Register
    using C1K = ftl::mmio::Field<1, 6, eC1K, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the PKHA A Size Register
    using CPKA = ftl::mmio::Field<1, 12, eCPKA, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the PKHA B Size Register
    using CPKB = ftl::mmio::Field<1, 13, eCPKB, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the PKHA N Size Register
    using CPKN = ftl::mmio::Field<1, 14, eCPKN, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the PKHA E Size Register
    using CPKE = ftl::mmio::Field<1, 15, eCPKE, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 2 Mode Register
    using C2M = ftl::mmio::Field<1, 16, eC2M, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 2 Data Size Registers
    using C2DS = ftl::mmio::Field<1, 18, eC2DS, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 2 Context Register
    using C2C = ftl::mmio::Field<1, 21, eC2C, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear the Class 2 Key Register
    using C2K = ftl::mmio::Field<1, 22, eC2K, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear Descriptor Sharing signal
    using CDS = ftl::mmio::Field<1, 25, eCDS, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear Class 2 Done Interrupt. Writing a 1 to this bit clears the Class 2 done interrupt.
    using C2D = ftl::mmio::Field<1, 26, eC2D, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear Class 1 Done Interrupt. Writing a 1 to this bit clears the Class 1 done interrupt.
    using C1D = ftl::mmio::Field<1, 27, eC1D, ftl::mmio::WO, ftl::mmio::Normal>;
    // Reset Class 2 CHA
    using C2RST = ftl::mmio::Field<1, 28, eC2RST, ftl::mmio::WO, ftl::mmio::Normal>;
    // Reset Class 1 CHA
    using C1RST = ftl::mmio::Field<1, 29, eC1RST, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear Output FIFO. Writing a 1 to this bit causes the Output FIFO to be cleared.
    using COF = ftl::mmio::Field<1, 30, eCOF, ftl::mmio::WO, ftl::mmio::Normal>;
    // Clear Input FIFO (and NFIFO)
    using CIF = ftl::mmio::Field<1, 31, eCIF, ftl::mmio::WO, ftl::mmio::Normal>;
  };  // struct C0cwrFields

