  // CCB 0 iNformation FIFO When STYPE != 10b
  struct C0nfifoFields {
    enum class eOC : std::uint32_t {
      // Allow the final word to be popped from the Output Data FIFO.
      ePOP_OFIFO_FINAL = 0,
      // Don't pop the final word from the Output Data FIFO.
      eDONT_POP_OFIFO_FINAL = 1,
    };

    enum class eBND : std::uint32_t {
      // Don't pad.
      eDONT_PAD = 0,
      // Pad to the next 16-byte boundary.
      ePAD_TO_BOUNDARY = 1,
    };

    enum class eFC1 : std::uint32_t {
      // Don't flush Class 1 data.
      eDONT_FLUSH_C1 = 0,
      // Flush Class 1 data.
      eFLUSH_C1 = 1,
    };

    enum class eFC2 : std::uint32_t {
      // Don't flush Class 2 data.
      eDONT_FLUSH_C2 = 0,
      // Flush Class 2 data.
      eFLUSH_C2 = 1,
    };

    enum class eLC1 : std::uint32_t {
      // This is not the last Class 1 data.
      eNOT_LAST_C1 = 0,
      // This is the last Class 1 data.
      eLAST_C1 = 1,
    };

    enum class eLC2 : std::uint32_t {
      // This is not the last Class 2 data.
      eNOT_LAST_C2 = 0,
      // This is the last Class 2 data.
      eLAST_C2 = 1,
    };

    enum class eDEST : std::uint32_t {
      // DECO Alignment Block. If DTYPE == Eh, data sent to the DECO Alignment Block is dropped. This is used to skip over input data. An error is generated if a DTYPE other than Eh (drop) or Fh (message) is used with the DECO Alignment Block destination.
      eDECO = 0,
      // Class 1.
      eCLASS_1 = 1,
      // Class 2.
      eCLASS_2 = 2,
      // Both Class 1 and Class 2.
      eCLASS_1_2 = 3,
    };

    // Data Length
    using DL = ftl::mmio::Field<12, 0, std::uint16_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Additional Source Types
    using AST = ftl::mmio::Field<1, 14, bool, ftl::mmio::WO, ftl::mmio::Normal>;
    // OFIFO Continuation - This bit causes the final word to not be popped from the Output Data FIFO.
    using OC = ftl::mmio::Field<1, 15, eOC, ftl::mmio::WO, ftl::mmio::Normal>;
    // Pad Type
    using PTYPE = ftl::mmio::Field<3, 16, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Boundary padding
    using BND = ftl::mmio::Field<1, 19, eBND, ftl::mmio::WO, ftl::mmio::Normal>;
    // Data Type
    using DTYPE = ftl::mmio::Field<4, 20, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Source Type
    using STYPE = ftl::mmio::Field<2, 24, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Flush Class 1. Flush the remainder of the data out of the Class 1 alignment block.
    using FC1 = ftl::mmio::Field<1, 26, eFC1, ftl::mmio::WO, ftl::mmio::Normal>;
    // Flush Class 2
    using FC2 = ftl::mmio::Field<1, 27, eFC2, ftl::mmio::WO, ftl::mmio::Normal>;
    // Last Class 1
    using LC1 = ftl::mmio::Field<1, 28, eLC1, ftl::mmio::WO, ftl::mmio::Normal>;
    // Last Class 2
    using LC2 = ftl::mmio::Field<1, 29, eLC2, ftl::mmio::WO, ftl::mmio::Normal>;
    // Destination
    using DEST = ftl::mmio::Field<2, 30, eDEST, ftl::mmio::WO, ftl::mmio::Normal>;
  };  // struct C0nfifoFields

