  // CCB 0 iNformation FIFO When STYPE == 10b
  struct C0nfifo2Fields {
    enum class ePS : std::uint32_t {
      // C2 CHA snoops pad data from padding block.
      eFROM_PAD_BLOCK = 0,
      // C2 CHA snoops pad data from OFIFO.
      eFROM_OFIFO = 1,
    };

    enum class eBM : std::uint32_t {
      // When padding, pad to power-of-2 boundary.
      eBOUND_PAD_NOT_MINUS_1 = 0,
      // When padding, pad to power-of-2 boundary minus 1 byte.
      eBOUND_PAD_MINUS_1 = 1,
    };

    enum class ePR : std::uint32_t {
      // No prediction resistance.
      eNO_PRED_RES = 0,
      // Prediction resistance.
      ePRED_RES = 1,
    };

    enum class ePTYPE : std::uint32_t {
      // All Zero.
      eALL_0 = 0,
      // Random with nonzero bytes.
      eRANDOM_NON_0 = 1,
      // Incremented (starting with 01h), followed by a byte containing the value N-1, i.e., if N==1, a single byte is output with value 0h.
      eINCREMENT_START_1 = 2,
      // Random.
      eRANDOM = 3,
      // All Zero with last byte containing the number of 0 bytes, i.e., if N==1, a single byte is output with value 0h.
      eALL_0_LAST_BYTE_NUMBER_OF_BYTES = 4,
      // Random with nonzero bytes with last byte 0.
      eRANDOM_NON_0_LAST_BYTE_0 = 5,
      // N bytes of padding all containing the value N-1.
      eALL_NUMBER_OF_BYTES_MINUS_1 = 6,
      // Random with nonzero bytes, with the last byte containing the value N-1.
      eRANDOM_NON_0_LAST_BYTE_NUMBER_OF_BYTES = 7,
    };

    enum class eBND : std::uint32_t {
      // Don't add boundary padding.
      eNO_PADDING = 0,
      // Add boundary padding.
      ePADDING = 1,
    };

    enum class eFC1 : std::uint32_t {
      // Don't flush the Class 1 data.
      eDONT_FLUSH_C1 = 0,
      // Flush the Class 1 data.
      eFLUSH_C1 = 1,
    };

    enum class eFC2 : std::uint32_t {
      // Don't flush the Class 2 data.
      eDONT_FLUSH_C2 = 0,
      // Flush the Class 2 data.
      eFLUSH_C2 = 1,
    };

    enum class eLC1 : std::uint32_t {
      // This is not the last Class 1 data.
      eNOT_LC1_DATA = 0,
      // This is the last Class 1 data.
      eLC1_DATA = 1,
    };

    enum class eLC2 : std::uint32_t {
      // This is not the last Class 2 data.
      eNOT_LC2_DATA = 0,
      // This is the last Class 2 data.
      eLC2_DATA = 1,
    };

    enum class eDEST : std::uint32_t {
      // DECO Alignment Block. If DTYPE is Eh, data sent to the DECO Alignment Block is dropped. This is used to skip over input data. An error is generated if a DTYPE other than Eh (drop) or Fh (message) is used with the DECO Alignment Block destination.
      eDECO = 0,
      // Class 1.
      eCLASS_1 = 1,
      // Class 2.
      eCLASS_2 = 2,
      // Both Class 1 and Class 2.
      eCLASS_1_2 = 3,
    };

    // Pad Length
    using PL = ftl::mmio::Field<7, 0, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Pad Snoop
    using PS = ftl::mmio::Field<1, 10, ePS, ftl::mmio::WO, ftl::mmio::Normal>;
    // Boundary Minus 1
    using BM = ftl::mmio::Field<1, 11, eBM, ftl::mmio::WO, ftl::mmio::Normal>;
    // Prediction Resistance - If PTYPE specifies random data, setting PR=1 causes the RNG to supply random data for prediction resistance (i
    using PR = ftl::mmio::Field<1, 15, ePR, ftl::mmio::WO, ftl::mmio::Normal>;
    // Pad Type
    using PTYPE = ftl::mmio::Field<3, 16, ePTYPE, ftl::mmio::WO, ftl::mmio::Normal>;
    // Boundary padding
    using BND = ftl::mmio::Field<1, 19, eBND, ftl::mmio::WO, ftl::mmio::Normal>;
    // Data Type
    using DTYPE = ftl::mmio::Field<4, 20, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Source Type
    using STYPE = ftl::mmio::Field<2, 24, std::uint8_t, ftl::mmio::WO, ftl::mmio::Normal>;
    // Flush Class 1. Flush the remainder of the data out of the Class 1 alignment block.
    using FC1 = ftl::mmio::Field<1, 26, eFC1, ftl::mmio::WO, ftl::mmio::Normal>;
    // Flush Class 2
    using FC2 = ftl::mmio::Field<1, 27, eFC2, ftl::mmio::WO, ftl::mmio::Normal>;
    // Last Class 1
    using LC1 = ftl::mmio::Field<1, 28, eLC1, ftl::mmio::WO, ftl::mmio::Normal>;
    // Last Class 2
    using LC2 = ftl::mmio::Field<1, 29, eLC2, ftl::mmio::WO, ftl::mmio::Normal>;
    // Destination
    using DEST = ftl::mmio::Field<2, 30, eDEST, ftl::mmio::WO, ftl::mmio::Normal>;
  };  // struct C0nfifo2Fields

