  // DECO0 Job Queue Control Register, most-significant half
  struct D0jqcrMsFields {
    enum class eSRC : std::uint32_t {
      // Job Ring 0
      eJR0 = 0,
      // Job Ring 1
      eJR1 = 1,
      // Job Ring 2
      eJR2 = 2,
      // Job Ring 3
      eJR3 = 3,
      // RTIC
      eRTIC = 4,
    };

    enum class eAMTD : std::uint32_t {
      // The Allowed Make Trusted Descriptor bit was NOT set.
      eAMTD_NOT_SET = 0,
      // The Allowed Make Trusted Descriptor bit was set.
      eAMTD_SET = 1,
    };

    enum class eSOB : std::uint32_t {
      // Shared Descriptor has NOT been loaded.
      eSD_NOT_LOADED = 0,
      // Shared Descriptor HAS been loaded.
      eSD_LOADED = 1,
    };

    enum class eDWS : std::uint32_t {
      // Double Word Swap is NOT set.
      eNO_DWS = 0,
      // Double Word Swap is set.
      eDWS = 1,
    };

    enum class eILE : std::uint32_t {
      // No byte-swapping is performed for immediate data transferred to or from the Descriptor Buffer.
      eNO_BYTE_SWAP = 0,
      // Byte-swapping is performed for immediate data transferred to or from the Descriptor Buffer.
      eBYTE_SWAP = 1,
    };

    enum class eFOUR : std::uint32_t {
      // DECO has not been given at least four words of the descriptor.
      eNOT_FOUR_WORDS = 0,
      // DECO has been given at least four words of the descriptor.
      eFOUR_WORDS = 1,
    };

    enum class eWHL : std::uint32_t {
      // DECO has not been given the whole descriptor.
      eNOT_WHOLE_DESC = 0,
      // DECO has been given the whole descriptor.
      eWHOLE_DESC = 1,
    };

    enum class eSING : std::uint32_t {
      // Do not tell DECO to execute the descriptor in single-step mode.
      eNOT_SINGLE_STEP_MODE = 0,
      // Tell DECO to execute the descriptor in single-step mode.
      eSINGLE_STEP_MODE = 1,
    };

    enum class eSTEP : std::uint32_t {
      // DECO has not been told to execute the next command in the descriptor.
      eDONT_STEP = 0,
      // DECO has been told to execute the next command in the descriptor.
      eSTEP = 1,
    };

    // Job ID
    using ID = ftl::mmio::Field<3, 0, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Job Source
    using SRC = ftl::mmio::Field<3, 8, eSRC, ftl::mmio::RO, ftl::mmio::Normal>;
    // Allow Make Trusted Descriptor
    using AMTD = ftl::mmio::Field<1, 15, eAMTD, ftl::mmio::RO, ftl::mmio::Normal>;
    // Shared Descriptor burst
    using SOB = ftl::mmio::Field<1, 16, eSOB, ftl::mmio::RW, ftl::mmio::Normal>;
    // Double word swap. Causes/allows dword swapping of addresses, and MOVE and MATH immediate values.
    using DWS = ftl::mmio::Field<1, 19, eDWS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Share From
    using SHR_FROM = ftl::mmio::Field<3, 24, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Immediate Little Endian
    using ILE = ftl::mmio::Field<1, 27, eILE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Four Words. job queue controller is passing at least 4 words of the Descriptor to DECO.
    using FOUR = ftl::mmio::Field<1, 28, eFOUR, ftl::mmio::RW, ftl::mmio::Normal>;
    // Whole Descriptor
    using WHL = ftl::mmio::Field<1, 29, eWHL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Single Step Mode
    using SING = ftl::mmio::Field<1, 30, eSING, ftl::mmio::RW, ftl::mmio::Normal>;
    // Step
    using STEP = ftl::mmio::Field<1, 31, eSTEP, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct D0jqcrMsFields

